package com.estateflow.service;
import com.estateflow.dao.*;import com.estateflow.exception.*;import com.estateflow.model.*;import com.estateflow.security.*;import java.util.List;
public final class VendorService{
 private final VendorDao dao;private final TransactionManager tx;private final AuditService audit;private final Authorizer auth;
 public VendorService(VendorDao dao,TransactionManager tx,AuditService audit,Authorizer auth){this.dao=dao;this.tx=tx;this.audit=audit;this.auth=auth;}
 public boolean isAvailable(){auth.require(Permission.VIEW_DATA);return dao.isAvailable();}
 public List<Vendor> search(String query,boolean includeInactive){auth.require(Permission.VIEW_DATA);ensure();return dao.search(query,includeInactive);}
 public Vendor get(long id)throws EntityNotFoundException{auth.require(Permission.VIEW_DATA);ensure();return dao.find(id).orElseThrow(()->new EntityNotFoundException("Vendor no longer exists."));}
 public Vendor save(Vendor input)throws EstateFlowException{auth.require(Permission.MANAGE_RECORDS);ensure();Vendor v=validate(input);return tx.inTransaction(()->{if(v.id()==null){Vendor row=dao.insert(v);audit.record("VENDOR",row.id(),"CREATED",null,AuditService.details("name",row.name(),"category",row.category()));return row;}Vendor old=dao.find(v.id()).orElseThrow(()->new EntityNotFoundException("Vendor no longer exists."));if(dao.update(v)==0)throw new EntityNotFoundException("Vendor no longer exists.");audit.record("VENDOR",v.id(),"UPDATED",AuditService.details("name",old.name(),"active",old.active()),AuditService.details("name",v.name(),"active",v.active()));return v;});}
 public void setActive(long id,boolean active)throws EstateFlowException{auth.require(Permission.MANAGE_RECORDS);Vendor old=get(id);if(old.active()==active)return;save(new Vendor(old.id(),old.name(),old.category(),old.phone(),old.email(),old.address(),old.notes(),active));}
 private void ensure(){if(!dao.isAvailable())throw new ConfigurationException("Vendor management requires the manual v1.7 migration db/migrations/v1.7_vendors_work_orders.sql.");}
 private static Vendor validate(Vendor v)throws ValidationException{if(v==null)throw new ValidationException("Vendor details are required.",null);String n=v.name()==null?"":v.name().trim();if(n.isEmpty()||n.length()>120)throw new ValidationException("Vendor name is required and must be at most 120 characters.","name");if(v.category()==null)throw new ValidationException("Choose a service category.","category");String email=trim(v.email(),120,"Email");if(email!=null&&!email.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$"))throw new ValidationException("Enter a valid vendor email address.","email");return new Vendor(v.id(),n,v.category(),trim(v.phone(),30,"Phone"),email,trim(v.address(),255,"Address"),trim(v.notes(),500,"Notes"),v.active());}
 private static String trim(String s,int max,String label)throws ValidationException{if(s==null||s.isBlank())return null;s=s.trim();if(s.length()>max)throw new ValidationException(label+" cannot exceed "+max+" characters.",label.toLowerCase());return s;}
}
